import {
  ArgumentsHost,
  BadRequestException,
  Catch,
  Controller,
  ExceptionFilter,
  Get,
  HttpException,
  Param,
  PipeTransform,
  Query,
  UseFilters,
} from '@nestjs/common';

class NumberPipe implements PipeTransform<string, number> {
  constructor(private readonly errorMessage: string) {}

  transform(value: string): number {
    const parsed = Number(value);
    if (Number.isNaN(parsed) || value.trim() === '') {
      throw new BadRequestException(this.errorMessage);
    }
    return parsed;
  }
}

@Catch()
export class MyParamFilter implements ExceptionFilter {
  public received: HttpException | undefined;

  catch(exception: unknown, host: ArgumentsHost) {
    this.received = exception as HttpException;
    const response = host.switchToHttp().getResponse();
    response
      .status(422)
      .json({ code: 'PARAMS_INVALID', count: 2 });
  }
}

@Controller('p')
export class AggregateParamErrorsController {
  @AggregateParamErrorsRoute()
  @Get(':id')
  public aggregated(
    @Param('id', new NumberPipe('A')) id: number,
    @Query('limit', new NumberPipe('B')) limit: number,
  ) {
    return `${id},${limit}`;
  }

  @Get('legacy/:id')
  public legacy(
    @Param('id', new NumberPipe('A')) id: number,
    @Query('limit', new NumberPipe('B')) limit: number,
  ) {
    return `${id},${limit}`;
  }

  @UseFilters(MyParamFilter)
  @Get('filtered/:id')
  public filtered(
    @Param('id', new NumberPipe('A')) id: number,
    @Query('limit', new NumberPipe('B')) limit: number,
  ) {
    return `${id},${limit}`;
  }
}

